1 SOUR MyApp
1 VERS 5.5.1
1 CHAR UTF-8
1 GEDC
2 VERS 5.5.1
0 @I1@ INDI
1 NAME John /Smith/
1 SEX M
0 @F1@ FAM
1 HUSB @I1@
1 WIFE @I999@
0 TRLR`;

      const gedcomFile = parser.parse(brokenGedcom);
