import { describe, it, expect } from "bun:test";
import { GedcomParser } from "./parser";
import { GedcomMapper } from "./mapper";

describe("GedcomMapper", () => {
  const parser = new GedcomParser();
  const mapper = new GedcomMapper();

  const sampleGedcom = `0 HEAD
1 SOUR MyApp
1 VERS 5.5.1
1 CHAR UTF-8
1 GEDC
2 VERS 5.5.1
0 @I1@ INDI
1 NAME John /Smith/
1 SEX M
1 BIRT
2 DATE 15 JAN 1985
2 PLAC New York, NY
1 OCCU Engineer
1 NOTE This is a note
1 FAMS @F1@
0 @I2@ INDI
1 NAME Jane /Smith/
1 SEX F
1 BIRT
2 DATE 10 JAN 1988
2 PLAC Boston, MA
1 FAMS @F1@
0 @I3@ INDI
1 NAME Robert /Smith/
1 SEX M
1 BIRT
2 DATE 1990
1 FAMC @F1@
0 @F1@ FAM
1 HUSB @I1@
1 WIFE @I2@
1 CHIL @I3@
1 MARR
2 DATE 10 JUN 1985
2 PLAC Boston, MA
0 TRLR`;

  const gedcomWithDeathDate = `0 HEAD
1 SOUR MyApp
1 VERS 5.5.1
1 CHAR UTF-8
1 GEDC
2 VERS 5.5.1
0 @I1@ INDI
1 NAME John /Smith/
1 SEX M
1 BIRT
2 DATE 15 JAN 1900
1 DEAT
2 DATE 10 JUN 1985
0 @I2@ INDI
1 NAME Jane /Smith/
1 SEX F
1 BIRT
2 DATE 10 JAN 1905
0 TRLR`;

